import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem127 preserva campos operacionais',()=>{for(const [id,titulo,expected,link] of [["QHCeO6rxelawGpcolRX1","Campainha Sem Fio Intelbras Cib 101 Com Bateria Preta","Campainha Sem Fio Intelbras Cib 101 Com Bateria Preta","https://www.mercadolivre.com.br/p/MLB42998422?wid=MLB6363542818"],["QIAwDGVurh7E0nsu2G7t","Chinelo Boaonda Ortopédico Bolt Nuvem Palmilha Conforto Leve","Chinelo Boaonda Bolt Nuvem","https://produto.mercadolivre.com.br/MLB-3609638507-chinelo-boaonda-ortopedico-bolt-nuvem-palmilha-conforto-leve-_JM?searchVariation=179931182528"],["QikFoLr76mfU8ijP9Nzr","Grand Theft Auto VI - PlayStation 5","Grand Theft Auto VI - PlayStation 5","https://www.mercadolivre.com.br/p/MLB74108173?wid=MLB7413456100"]]){const p={id,titulo,link,linkAfiliado:'https://meli.la/preservar',preco:'preservar'},x=correctProductData(p);assert.ok(x.comentario.length>=180);assert.equal(x.titulo,expected);for(const k of ['id','link','linkAfiliado','preco'])assert.equal(x[k],p[k]);assert.deepEqual(correctProductData(x),x);}});
